import{M as e}from"./chunks/McpFeature.CtDtsj20.js";import{o,c as t,E as r,a3 as l}from"./chunks/framework.WFmvnizL.js";const p=JSON.parse('{"title":"哪吒 MCP：面向 AI Agent 的智能运维与服务器管理","description":"用哪吒 MCP 连接 Codex、OpenClaw、Claude Code，把服务器监控转为自然语言驱动的巡检、故障诊断、授权命令执行、文件管理与变更验证，了解实际场景和接入方式。","frontmatter":{"title":"哪吒 MCP：面向 AI Agent 的智能运维与服务器管理","description":"用哪吒 MCP 连接 Codex、OpenClaw、Claude Code，把服务器监控转为自然语言驱动的巡检、故障诊断、授权命令执行、文件管理与变更验证，了解实际场景和接入方式。","outline":"deep","keywords":["哪吒 MCP","AI 运维","智能服务器管理","Codex","OpenClaw","Claude Code","Model Context Protocol"],"faq":[{"question":"哪吒 MCP 是什么？","answer":"哪吒 MCP 是连接 AI 助手与服务器的标准工具接口，提供服务器清单、当前状态、远程命令和文件操作。AI 负责理解需求，哪吒负责提供实际操作工具。"},{"question":"可以与 Codex、OpenClaw、Claude Code 一起使用吗？","answer":"可以使用支持 HTTP MCP 和 Bearer Token 的客户端接入。Codex 和 Claude Code 支持远程 MCP；OpenClaw 需配置当前运行时可用的 MCP 客户端或 mcporter。"},{"question":"哪吒内置大模型或聊天机器人吗？","answer":"不内置大模型。哪吒提供监控与运维工具，模型、对话、规划和工作流编排由你选择的 AI 客户端负责。"},{"question":"MCP 能直接配置告警、查询历史指标或管理所有面板设置吗？","answer":"MCP 提供服务器状态、命令和文件工具。告警与任务配置、历史指标和其他面板设置，需要使用哪吒后台或 REST API。"},{"question":"能实现自动化故障处置吗？","answer":"可以搭建诊断、授权处置和复核流程。定时运行、接收告警和操作确认由客户端或外部工作流提供；哪吒触发任务可以执行审阅后的脚本。"},{"question":"自托管后，数据还会发送给 AI 服务商吗？","answer":"Dashboard 与服务器 Agent 可以自托管。使用外部模型时，客户端可能将提示词、工具结果及读取到的日志或文件发送给模型服务商；具体取决于模型部署方式和客户端的数据策略。"}]},"headers":[],"relativePath":"guide/ai-operations.md","filePath":"guide/ai-operations.md","lastUpdated":1792674226000}'),n={name:"guide/ai-operations.md"},c=Object.assign(n,{setup(i){return(s,a)=>(o(),t("div",null,[r(e),a[0]||(a[0]=l("",44))]))}});export{p as __pageData,c as default};
